      out.write("        }).join('<i class=\"bi bi-arrow-right text-muted me-1\"></i>');\n");
      out.write("    } else {\n");
      out.write("        escHtml = '<span class=\"text-muted small\">Chưa cấu hình cấp vượt hạn mức.</span>';\n");
      out.write("    }\n");
      out.write("    document.getElementById('simEscalatedChain').innerHTML = escHtml;\n");
      out.write("}\n");
